def load_state_dict(self, state_dict: Dict[str, Any]) -> None:
    """
    This function loads the state of a CombinedStreamingDataset instance from a given state dictionary. It updates the state of each dataset within the CombinedStreamingDataset and, if applicable, updates the number of samples yielded by the streaming dataloader to avoid repeating samples.

    Input-Output Arguments
    :param self: CombinedStreamingDataset. An instance of the CombinedStreamingDataset class.
    :param state_dict: Dict[str, Any]. A dictionary containing the state information for the CombinedStreamingDataset and its constituent datasets. It is used to restore the state of the CombinedStreamingDataset and its datasets.
    :return: None. There are no return values.

    """
    if state_dict is None or not state_dict:
        raise ValueError("State dictionary is empty or None")

    if "dataset" in state_dict:
        for i, dataset in enumerate(self._datasets):
            if str(i) in state_dict["dataset"]:
                dataset.load_state_dict(state_dict["dataset"][str(i)])
            else:
